export const roleName = user => user?.role === 'admin' ? '管理员' : user?.canEdit ? '已授权编辑' : '仅查看';
export const actionNames = {
  'account.register': '注册账号', 'account.login': '登录', 'account.logout': '退出登录',
  'account.password': '修改密码', 'audit.export': '导出操作日志',
  'account.recovery.request': '申请找回密码', 'account.recovery.reset': '管理员重置密码', 'account.recovery.reject': '拒绝找回申请',
  'recipes.sync': '同步菜谱', 'recipe.view': '查看菜谱', 'recipe.history': '查看历史版本',
  'recipe.create': '新增菜谱', 'recipe.update': '编辑菜谱', 'recipe.delete': '删除菜谱',
  'recipe.restore': '恢复历史版本', 'recipe.import': '导入菜谱', 'recipe.favorite': '收藏操作',
  'recipe.cook': '开始跟着做', 'recipe.checkin': '制作完成打卡', 'backup.export': '导出备份',
  'permission.request': '申请编辑权限', 'permission.approve': '批准编辑权限',
  'permission.reject': '拒绝申请', 'permission.revoke': '撤销编辑权限',
};
const statusNames = { pending: '待审核', approved: '已批准', rejected: '未通过', revoked: '已撤销' };
const time = value => new Date(value).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false });

export function myPages({ icon, esc }) {
  const back = () => `<button class="text-button my-back" data-action="navigate" data-page="my">${icon('back')}返回我的</button>`;
  const link = (page, mark, title, note) => `<button class="my-link" data-action="navigate" data-page="${page}"><span class="panel-icon">${icon(mark)}</span><span><strong>${title}</strong><small>${note}</small></span>${icon('arrow')}</button>`;
  return {
    back,
    overview(user, favoriteCount, recoveryCount = 0) {
      return `<h1 class="page-title">我的</h1><p class="page-lead">管理自己的账号、权限和菜谱备份。</p><section class="panel my-profile"><div class="panel-icon">${icon('people')}</div><div><h2>${esc(user?.displayName || '')}</h2><p><span class="role-badge">${roleName(user)}</span> · ${favoriteCount} 道个人收藏</p></div></section><div class="my-sections"><section class="panel"><h2>账号与权限</h2>${link('account', 'people', '我的账号', '用户名、登录 ID 与登录状态')}${user?.role !== 'admin' ? link('permissions', 'lock', '账号授权', '说明申请原因，查看审批结果') : ''}</section><section class="panel"><h2>下厨记录</h2>${link('checkins', 'check', '我的打卡', '记录做过的菜与每一次下厨心得')}</section><section class="panel"><h2>数据管理</h2>${link('backup', 'backup', '菜谱备份', '下载备份、导入菜谱与恢复数据')}</section>${user?.role === 'admin' ? `<section class="panel"><h2>管理员工具</h2>${link('permissions', 'lock', '账号授权', '审批编辑申请，管理与撤销账号权限')}${link('recovery', 'lock', '密码找回', recoveryCount ? `${recoveryCount} 条待处理申请，请核实身份后重置` : '查看找回申请，重置后线下告知用户')}${link('logs', 'clock', '操作日志', '查看用户行为，按账号与操作搜索')}</section>` : ''}<section class="panel"><h2>应用版本</h2><div data-version-controls class="version-controls"></div></section></div>`;
    },
    permissions(user, data, error = '') {
      const admin = user?.role === 'admin';
      const requests = data?.requests || [], pending = requests.filter(item => item.status === 'pending');
      const entry = item => `<article class="request-card"><div class="request-head"><strong>${esc(item.displayName)}</strong><span class="status-badge status-${item.status}">${statusNames[item.status]}</span></div><p class="request-reason">${esc(item.reason)}</p><p class="small-note">申请时间：${esc(time(item.createdAt))}${item.reviewedAt ? `<br>处理时间：${esc(time(item.reviewedAt))}` : ''}</p>${item.note ? `<p class="review-note">管理员备注：${esc(item.note)}</p>` : ''}${admin && item.status === 'pending' ? `<div class="management-actions"><button class="button primary" data-action="permission-decision" data-kind="approve" data-id="${esc(item.id)}" data-user="${esc(item.userId)}">批准编辑</button><button class="button ghost" data-action="permission-decision" data-kind="reject" data-id="${esc(item.id)}" data-user="${esc(item.userId)}">拒绝申请</button></div>` : ''}</article>`;
      return `${back()}<div class="section-head"><h1 class="page-title">账号授权</h1><button class="button ghost" data-action="reload-permissions">刷新状态</button></div><p class="page-lead">${admin ? '只有 wupanfeng 管理员可以审批和撤销权限。授权包含新增、编辑、删除、导入及恢复历史版本。' : '当前权限：' + roleName(user) + '。编辑权限需说明原因，由 wupanfeng 管理员审核。'}</p>${error ? `<p class="form-error" role="alert">${esc(error)}</p>` : ''}${!data && !error ? '<p class="page-lead" role="status">正在加载授权信息…</p>' : ''}${!admin && data ? `<section class="panel">${user.canEdit ? '<h2>已获得编辑权限</h2><p>现在可以新增、编辑、删除、导入菜谱和恢复历史版本。管理员可以撤销授权。</p>' : pending.length ? '<h2>申请已提交</h2><p>请等待管理员审核。可以继续查看菜谱，点击“刷新状态”查看结果。</p>' : '<h2>申请编辑权限</h2><form id="permission-request-form"><label class="field"><span class="field-label">申请原因</span><textarea name="reason" required minlength="5" maxlength="500" rows="4" placeholder="说明希望编辑哪些菜谱，以及编辑用途（5～500 字）"></textarea></label><p class="small-note">获批后可新增、修改、删除、导入菜谱和恢复历史版本。</p><p id="permission-error" class="form-error" role="alert" hidden></p><button type="submit" class="button primary">提交申请</button></form>'}</section>` : ''}${admin && data ? `<section class="panel"><h2>待审核申请 · ${pending.length}</h2><div class="management-list">${pending.length ? pending.map(entry).join('') : '<p class="empty-management">暂时没有待审核的申请。</p>'}</div></section><section class="panel management-panel"><h2>账号权限 · ${data.accounts.length}</h2><div class="management-list">${data.accounts.map(account => `<article class="account-row"><div><strong>${esc(account.displayName)}</strong><span class="role-badge">${roleName(account)}</span><p class="small-note account-id">${esc(account.id)}</p></div>${account.role !== 'admin' && account.canEdit ? `<button class="button danger" data-action="permission-decision" data-kind="revoke" data-user="${esc(account.id)}" data-id="${esc(requests.find(item => item.userId === account.id && item.status === 'approved')?.id || '')}">撤销编辑</button>` : ''}</article>`).join('')}</div></section>` : ''}${data ? `<section class="panel management-panel"><h2>${admin ? '已处理申请' : '我的申请记录'}</h2><div class="management-list">${(admin ? requests.filter(item => item.status !== 'pending') : requests).map(entry).join('') || '<p class="empty-management">暂无申请记录。</p>'}</div></section>` : ''}`;
    },
    logs(user, data, { query = '', result = '', error = '', loading = false, exporting = false } = {}) {
      if (user?.role !== 'admin') return `${back()}<p class="page-lead">只有管理员可以查看操作日志。</p>`;
      return `${back()}<h1 class="page-title">操作日志</h1><p class="page-lead">记录登录、注册、菜谱查看与修改、备份和授权行为。日志显示时间、账号、操作对象和结果。</p><form id="audit-filter-form" class="audit-filters"><label class="search-box">${icon('search')}<input name="query" type="search" aria-label="搜索日志" maxlength="100" placeholder="搜索账号、操作或菜名" value="${esc(query)}"></label><select name="result" class="sort-select" aria-label="操作结果"><option value="">所有结果</option><option value="success" ${result === 'success' ? 'selected' : ''}>成功</option><option value="denied" ${result === 'denied' ? 'selected' : ''}>权限拦截</option><option value="failed" ${result === 'failed' ? 'selected' : ''}>未完成</option></select><button class="button ghost" type="submit" ${loading ? 'disabled' : ''}>${loading ? '读取中…' : '筛选日志'}</button></form><div class="audit-export-actions"><p>导出当前筛选条件下的全部记录（不受分页限制）。时间采用北京时间。</p><div class="management-actions"><button class="button ghost" data-action="export-audit" data-format="csv" ${loading || exporting ? "disabled" : ""}>${exporting ? "正在导出…" : "导出 CSV"}</button><button class="button ghost" data-action="export-audit" data-format="json" ${loading || exporting ? "disabled" : ""}>导出 JSON</button></div></div>${error ? `<p class="form-error" role="alert">${esc(error)}</p>` : ''}<section class="panel audit-panel"><div class="audit-list">${data?.items.map(item => `<article class="audit-row"><div class="request-head"><strong>${esc(actionNames[item.action] || item.action)}</strong><span class="status-badge status-${item.result === 'success' ? 'approved' : 'rejected'}">${{ success: '成功', denied: '权限拦截', failed: '未完成' }[item.result] || esc(item.result)}</span></div><p>${esc(item.displayName)}${item.target ? ` · ${esc(item.target)}` : ''}</p><p class="small-note">${esc(time(item.createdAt))}${item.userId ? `<br><span class="account-id">${esc(item.userId)}</span>` : ''}</p></article>`).join('') || `<p class="empty-management">${loading ? '正在读取操作日志…' : '暂无符合条件的操作记录。'}</p>`}</div>${data?.cursor ? '<button class="button ghost load-more" data-action="load-more-logs">加载更早记录</button>' : ''}</section><p class="small-note">日志中的“查看菜谱”和“开始跟着做”为联网时上报，离线浏览不会产生这些记录。</p>`;
    },
  };
}
